def _pick_default(legal):
    for action in DEFAULT_ACTION_ORDER:
        if action in legal:
            return action
    return int(legal[0])


def _straight_high_from_mask(mask: int) -> int:
    for high in range(14, 5 - 1, -1):
        window = 0
        for rank in range(high - 4, high + 1):
            window += 1 if mask & (1 << rank) else 0
        if window == 5:
            return high
    if (mask & (1 << 14)) and all(mask & (1 << r) for r in (2, 3, 4, 5)):
        return 5
    return 0


def _straight_draw_kind(mask: int) -> int:
    """Return 2 for open-ended, 1 for gutshot, 0 otherwise."""
    present = [False] * 15
    for rank in range(2, 15):
        present[rank] = bool(mask & (1 << rank))
    if present[14]:
        present[1] = True

    run = 0
    best_run = 0
    for rank in range(1, 15):
        if present[rank]:
            run += 1
            if run > best_run:
                best_run = run
        else:
            run = 0
    if best_run >= 4:
        return 2

    for start in range(1, 11):
        count = 0
        for rank in range(start, start + 5):
            if present[rank]:
                count += 1
        if count == 4:
            return 1
    return 0


def _best_hand_value(cards):
    ranks = []
    suit_ranks = [[] for _ in range(4)]
    rank_counts = [0] * 15
    suit_masks = [0] * 4
    rank_mask = 0

    for card in cards:
        suit = SUIT_TO_INDEX[card[0]]
        rank = RANK_TO_VALUE[card[1]]
        ranks.append(rank)
        suit_ranks[suit].append(rank)
        rank_counts[rank] += 1
        rank_mask |= 1 << rank
        suit_masks[suit] |= 1 << rank

