    best_sf = 0
    for suit in range(4):
        if len(suit_ranks[suit]) >= 5:
            high = _straight_high_from_mask(suit_masks[suit])
            if high > best_sf:
                best_sf = high
    if best_sf:
        return (8, best_sf)

    quads = 0
