RANK_TO_VAL = {r: i + 2 for i, r in enumerate(RANKS)}
SUIT_TO_IDX = {"S": 0, "H": 1, "D": 2, "C": 3}


def _pick_default(legal: tuple[int, ...] | list[int]) -> int:
    for action in (ACTION_CHECK, ACTION_CALL, ACTION_FOLD, ACTION_RAISE):
