    return int(legal[0])


def _card_rank(card: str) -> int:
    # State cards are like "SA" (suit, rank).
    return RANK_TO_VAL[card[1]]


def _card_suit(card: str) -> str:
    return card[0]


def _highest_straight_high(rank_mask: int) -> int:
    # rank_mask uses bit (1 << r) for r in [2..14], plus optional Ace-low bit at 1.
    # Returns 0 if no straight, otherwise the high card of the best straight (5..14).
    # Wheel straight is returned as 5.
    for high in range(14, 4, -1):
        seq = 0
        for r in range(high - 4, high + 1):
            seq |= 1 << r
        if rank_mask & seq == seq:
            return high
    # Wheel: A2345, represented by bits 14 and 1..5 (we set bit 1 when Ace exists)
    wheel = (1 << 1) | (1 << 2) | (1 << 3) | (1 << 4) | (1 << 5)
    if rank_mask & wheel == wheel:
        return 5
    return 0


def _popcount(x: int) -> int:
    return x.bit_count()


