        r = RANK_TO_VAL[c[1]]
        suit_counts[s] += 1
        rank_counts[r] += 1
        ranks.append(r)
        suits.append(s)

    # groups sorted by (count, rank) desc for ranks present.
    groups: list[tuple[int, int]] = []
    for r in range(14, 1, -1):
        c = rank_counts[r]
        if c:
            groups.append((c, r))
    groups.sort(reverse=True)

    flush_suit = -1
    for s in range(4):
        if suit_counts[s] >= 5:
            flush_suit = s
            break

    rank_mask = 0
    for r in range(2, 15):
        if rank_counts[r]:
            rank_mask |= 1 << r

